import React from 'react';
import { Cpu } from 'lucide-react';

const Footer = () => {
  return (
    <footer
      style={{
        background: '#ffffff',
        borderTop: '1px solid #E2E8F0',
        padding: '0.85rem 1.75rem',
        marginTop: '2rem',
        display: 'flex',
        justify: 'space-between',
        alignItems: 'center',
        flexWrap: 'wrap',
        gap: '1rem',
        fontSize: '0.8rem',
        color: '#64748B',
        fontWeight: '700',
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
        <Cpu size={16} style={{ color: '#2563EB' }} />
        <span>TexTwin Digital Twin Platform</span>
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: '1.25rem' }}>
        <span>Version: <strong style={{ color: '#0F172A' }}>v1.0</strong></span>
        <span>•</span>
        <span>Environment: <strong style={{ color: '#059669' }}>Production</strong></span>
        <span>•</span>
        <span>Copyright: <strong style={{ color: '#0F172A' }}>2026 TexTwin</strong></span>
      </div>
    </footer>
  );
};

export default Footer;
